/** Plan last used to size this org's buckets, so a change resets them. */
const appliedPlan = new Map<OrgId, PlanId>();

function dropOrgBuckets(orgId: OrgId): void {
  const prefix = `${orgId}:`;
  for (const key of buckets.keys()) {
    if (key.startsWith(prefix)) buckets.delete(key);
  }
}

/** Records an org's plan so subsequent bucket sizes scale with its quota. */
export function setOrgPlan(orgId: OrgId, plan: PlanId): void {
  planByOrg.set(orgId, plan);
  if (appliedPlan.get(orgId) !== plan) {
    dropOrgBuckets(orgId);
    appliedPlan.set(orgId, plan);
  }
}

/**
 * Subscription plan when one exists, otherwise the plan stored on the
 * workspace. An explicit `setOrgPlan` wins so callers can pin a plan before
 * a subscription row exists. Lookup failures (no database) stay on free.
 */
async function resolvePlan(orgId: OrgId): Promise<PlanId> {
  const pinned = planByOrg.get(orgId);
  if (pinned) return pinned;

  try {
    const { findSubscription } = await import(
      "@/server/repositories/subscription-repository"
    );
    const subscription = await findSubscription(orgId);
    if (subscription) return subscription.plan;

    const { findOrgById } = await import(
      "@/server/repositories/organization-repository"
    );
    const org = await findOrgById(orgId);
    if (org) return org.plan;
  } catch {
    return "free";
  }

  return "free";
}

